using System.Security.Cryptography;
using System.Text.Json;
using TogetherServer;

namespace TogetherServer.FeatureChecks;

// Generated bytes, disposable files and fake time only. No app, process,
// listener, native desktop, browser, production state or game is opened.
internal static class WorldPeerPreparationProgressChecks
{
    private const int ChunkBytes = 512 * 1024;
    private const string Phase = "RetainingSource";
    private const string Message = "Keeping the verified save on this PC.";

    internal static Task RunAsync(string root)
    {
        ChunkedHashAndCancellation();
        VerifyGeneratedFiles(root);
        ObserverFailuresKeepVerifiedCopy(root);
        MeaningfulProgressOnly();
        return Task.CompletedTask;
    }

    private static void ChunkedHashAndCancellation()
    {
        var bytes = new byte[ChunkBytes * 2 + 37];
        for (var index = 0; index < bytes.Length; index++) bytes[index] = (byte)(index * 31 + 17);
        var observations = new List<long>();
        using (var input = new ObservedStream(bytes))
        {
            var digest = WorldPeerPayloadHash.Hash(input, default, observations.Add);
            Require(digest == Convert.ToHexString(SHA256.HashData(bytes)) &&
                observations.SequenceEqual(new long[] { ChunkBytes, ChunkBytes * 2L, bytes.LongLength }),
                "chunked verification changed SHA-256 or omitted real byte advancement");
        }
        using (var input = new ObservedStream(bytes))
            Require(WorldPeerPayloadHash.Hash(input, default, _ => throw new InvalidOperationException("display only")) ==
                Convert.ToHexString(SHA256.HashData(bytes)), "a failed display sink changed the verified digest");
        using (var empty = new ObservedStream([]))
        {
            var calls = 0;
            Require(WorldPeerPayloadHash.Hash(empty, default, _ => calls++) ==
                Convert.ToHexString(SHA256.HashData(Array.Empty<byte>())) && calls == 0,
                "an empty file fabricated transferred bytes or changed its signed hash");
        }
        using (var canceled = new CancellationTokenSource())
        using (var input = new ObservedStream(bytes))
        {
            canceled.Cancel();
            Expect<OperationCanceledException>(() => WorldPeerPayloadHash.Hash(input, canceled.Token),
                "a pre-canceled hash completed");
            Require(input.ReadCalls == 0, "a pre-canceled hash read payload bytes");
        }
        using (var canceled = new CancellationTokenSource())
        using (var input = new ObservedStream(bytes))
        {
            Expect<OperationCanceledException>(() => WorldPeerPayloadHash.Hash(input, canceled.Token, _ => canceled.Cancel()),
                "cancellation during a large file returned an accepted hash");
            Require(input.ReadCalls == 1 && input.Position == ChunkBytes,
                "large-file cancellation was delayed until the complete file was read");
        }
        using (var input = new ObservedStream(bytes) { FailAfterReads = 1 })
            Expect<IOException>(() => WorldPeerPayloadHash.Hash(input, default),
                "an input read failure was swallowed as a display error");
    }

    private static void VerifyGeneratedFiles(string root)
    {
        var privateMarker = Guid.NewGuid().ToString("N");
        var directory = Path.Combine(root, "source-progress-" + privateMarker);
        Directory.CreateDirectory(directory);
        var files = new List<(string Path, SharedWorldFile Fact)>();
        for (var index = 0; index < 315; index++)
        {
            var bytes = new byte[index == 1 ? ChunkBytes * 2 + 37 : index % 3 == 0 ? 0 : index % 17 + 1];
            for (var offset = 0; offset < bytes.Length; offset++) bytes[offset] = (byte)(index + offset);
            var name = $"private-file-{index:D3}-{privateMarker}.bin";
            var path = Path.Combine(directory, name);
            File.WriteAllBytes(path, bytes);
            files.Add((path, new(name, bytes.LongLength, Convert.ToHexString(SHA256.HashData(bytes)))));
        }
        var before = Fingerprints(directory);
        var total = files.Sum(item => item.Fact.Length);
        var updates = new List<WorldPeerSourceProgress>();
        var clock = new FakeClock();
        var store = new LocalHostingProgressStore(clock);
        var connection = new object();
        var profile = Guid.NewGuid();
        using var operation = store.Begin(connection, profile);
        long completedBytes = 0;
        var completedFiles = 0;
        void Report(long currentBytes)
        {
            clock.Advance(TimeSpan.FromSeconds(1));
            var update = new WorldPeerSourceProgress(Phase, Message, currentBytes, total, completedFiles, files.Count);
            WorldPeerSourceProgress.Report(value => { updates.Add(value); operation.Source(value); }, update);
        }
        Report(0);
        foreach (var file in files)
        {
            WorldPeerPayloadHash.VerifyFile(file.Path, file.Fact, default,
                count => Report(completedBytes + count));
            completedBytes += file.Fact.Length;
            completedFiles++;
            Report(completedBytes); // Zero-byte files still complete real work.
        }
        Require(updates.Any(value => value.CompletedBytes > 0 && value.CompletedFiles == 1) &&
            updates.Count(value => value.CompletedFiles > 0) >= 315 &&
            store.Read(connection, profile) is { State: "Working", CompletedFiles: 315, TotalFiles: 315, Percent: 100 } observed &&
            observed.ReceivedBytes == total && observed.TotalBytes == total,
            "315-file verification lost chunk/file progress or claimed preparation completed after hashing");
        var serialized = JsonSerializer.Serialize(updates);
        Require(!serialized.Contains(privateMarker, StringComparison.Ordinal) &&
            !serialized.Contains(profile.ToString(), StringComparison.OrdinalIgnoreCase) &&
            !serialized.Contains("private-file-", StringComparison.Ordinal),
            "display callbacks exposed a source path, filename or world identity");
        WorldPeerSourceProgress.Report(_ => throw new InvalidOperationException("display only"), updates[^1]);

        var large = files[1];
        using (var canceled = new CancellationTokenSource())
            Expect<OperationCanceledException>(() => WorldPeerPayloadHash.VerifyFile(large.Path, large.Fact,
                canceled.Token, _ => canceled.Cancel()), "canceled file verification completed");
        Expect<InvalidDataException>(() => WorldPeerPayloadHash.VerifyFile(large.Path,
            large.Fact with { Length = large.Fact.Length + 1 }, default), "a changed file length verified");
        Expect<InvalidDataException>(() => WorldPeerPayloadHash.VerifyFile(large.Path,
            large.Fact with { Sha256 = new string('0', 64) }, default,
            _ => throw new InvalidOperationException("display only")),
            "a throwing display sink authorized a bad signed hash");
        Expect<InvalidDataException>(() => WorldPeerPayloadHash.VerifyFile(Path.Combine(directory, "missing.bin"),
            large.Fact, default), "a missing source file verified");
        Require(Fingerprints(directory).OrderBy(item => item.Key).SequenceEqual(before.OrderBy(item => item.Key)) &&
            !File.Exists(Path.Combine(directory, "latest.json")),
            "verification/cancellation changed source bytes or promoted a playable pointer");
    }

    private static void MeaningfulProgressOnly()
    {
        var clock = new FakeClock();
        var store = new LocalHostingProgressStore(clock);
        var connection = new object();
        var other = new object();
        var profile = Guid.NewGuid();
        using var first = store.Begin(connection, profile);
        var progress = new WorldPeerSourceProgress(Phase, Message, 10, 100, 1, 315);
        first.Source(progress);
        var saved = store.Read(connection, profile)!;
        clock.Advance(TimeSpan.FromMinutes(2));
        first.Source(progress);
        Require(store.Read(connection, profile) == saved,
            "repeated polling renewed the idle deadline without source work");
        first.Source(progress with { CompletedBytes = 5 });
        first.Source(progress with { CompletedFiles = 0 });
        Require(store.Read(connection, profile) == saved,
            "a stale regressing source callback renewed the idle deadline");
        foreach (var invalid in new[] { progress with { CompletedBytes = -1 }, progress with { TotalBytes = 9 },
            progress with { CompletedFiles = -1 }, progress with { TotalFiles = 0 } }) first.Source(invalid);
        Require(store.Read(connection, profile) == saved, "invalid progress changed a measured operation");
        first.Source(progress with { CompletedFiles = 2 });
        Require(store.Read(connection, profile) is { CompletedFiles: 2, ReceivedBytes: 10 } advanced &&
            advanced.UpdatedUtc > saved.UpdatedUtc,
            "finishing a zero-byte file did not advance the observed work time");

        using var second = store.Begin(other, profile);
        first.Source(progress with { CompletedBytes = 100, CompletedFiles = 315 });
        first.Complete(true, "Stale completion");
        Require(store.Read(connection, profile) is null && store.Read(other, profile) is { Phase: "Permission", State: "Working" },
            "a previous connection's work replaced the current operation");
        second.Source(new(Phase, Message, 0, 0, 315, 315));
        Require(store.Read(other, profile) is { Percent: null, CompletedFiles: 315, State: "Working" },
            "zero-byte file completion fabricated byte progress or hosting readiness");
        second.Complete(true, "Prepared");
        var terminal = store.Read(other, profile);
        clock.Advance(TimeSpan.FromMinutes(2));
        second.Source(progress);
        second.Dispose();
        Require(store.Read(other, profile) == terminal && terminal is { State: "Completed", Percent: null },
            "a late source callback or disposal changed a completed operation");
        using var canceled = store.Begin(connection, profile);
        canceled.Dispose();
        var stopped = store.Read(connection, profile);
        canceled.Source(progress);
        Require(store.Read(connection, profile) == stopped && stopped is { State: "Failed", Percent: null },
            "source work after cancellation claimed completion");
    }

    private static void ObserverFailuresKeepVerifiedCopy(string root)
    {
        using var owner = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        var copyRoot = Path.Combine(root, "progress-observer-" + Guid.NewGuid().ToString("N"));
        var bytes = new byte[ChunkBytes + 31];
        for (var index = 0; index < bytes.Length; index++) bytes[index] = (byte)(index * 13 + 5);
        var facts = new SharedWorldFile[]
        {
            new("empty.dat", 0, Convert.ToHexString(SHA256.HashData(Array.Empty<byte>()))),
            new("complete.dat", bytes.LongLength, Convert.ToHexString(SHA256.HashData(bytes)))
        };
        var version = SharedWorldService.SignVersion(new(4, Guid.NewGuid(), 1, null, Guid.NewGuid(),
            GameKinds.Fixture, "SyntheticProgress", DateTimeOffset.UtcNow, SharedWorldCaptureKinds.PostStopBackup,
            Guid.NewGuid(), new(2456, false, "Unknown", [], []), facts, "", "", ""), owner);
        var destination = Path.Combine(copyRoot, version.VersionHash);
        var payload = Path.Combine(destination, SharedWorldService.PayloadDirectory);
        Directory.CreateDirectory(payload);
        File.WriteAllBytes(Path.Combine(payload, "empty.dat"), []);
        File.WriteAllBytes(Path.Combine(payload, "complete.dat"), bytes);
        var metadata = JsonSerializer.SerializeToUtf8Bytes(version, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        File.WriteAllBytes(Path.Combine(destination, "version.json"), metadata);
        File.WriteAllBytes(Path.Combine(copyRoot, "latest.json"), metadata);
        var original = CopyFingerprints();
        var completedFileCallbacks = 0;
        void ThrowAfterFile(long _, long __, int files, int ___)
        {
            if (files == 0) return;
            completedFileCallbacks++;
            throw new InvalidDataException("Synthetic display sink failed.");
        }
        // The observer exception must not enter VerifyStage's integrity-failure
        // repair path and truncate an otherwise valid partial payload file.
        WorldPeerFileTransfer.VerifyStage(root, payload, version, default, ThrowAfterFile);
        Require(CopyFingerprints().OrderBy(item => item.Key).SequenceEqual(original.OrderBy(item => item.Key)),
            "a final-file progress failure reset valid source bytes as though integrity failed");
        var latest = FriendLink.ReadReceivedLatest(copyRoot, default, ThrowAfterFile);
        Require(latest?.VersionHash == version.VersionHash,
            "a final-file display failure rejected the valid completed pointer");
        using (var lease = WorldPeerVerifiedCopy.Open(root, destination, version, default, ThrowAfterFile))
            Require(completedFileCallbacks >= facts.Length * 3,
                "final-file progress notifications were omitted instead of safely isolating failed sinks");
        Require(CopyFingerprints().OrderBy(item => item.Key).SequenceEqual(original.OrderBy(item => item.Key)),
            "a throwing verification observer changed a completed source or its pointer");

        Dictionary<string, string> CopyFingerprints() => Directory.EnumerateFiles(copyRoot, "*", SearchOption.AllDirectories)
            .ToDictionary(path => Path.GetRelativePath(copyRoot, path),
                path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))), StringComparer.Ordinal);
    }

    private static Dictionary<string, string> Fingerprints(string root) => Directory.EnumerateFiles(root)
        .ToDictionary(path => Path.GetFileName(path)!, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))), StringComparer.Ordinal);
    private static void Expect<T>(Action action, string message) where T : Exception
    {
        try { action(); }
        catch (Exception error) when (error is T) { return; }
        throw new InvalidOperationException(message);
    }
    private static void Require(bool value, string message) { if (!value) throw new InvalidOperationException(message); }
    private sealed class FakeClock : TimeProvider
    {
        private DateTimeOffset current = new(2026, 10, 25, 18, 0, 0, TimeSpan.Zero);
        public override DateTimeOffset GetUtcNow() => current;
        internal void Advance(TimeSpan elapsed) => current += elapsed;
    }
    private sealed class ObservedStream(byte[] bytes) : MemoryStream(bytes, writable: false)
    {
        internal int ReadCalls { get; private set; }
        internal int? FailAfterReads { get; init; }
        public override int Read(Span<byte> buffer)
        {
            if (FailAfterReads is { } limit && ReadCalls >= limit) throw new IOException("Synthetic read failed.");
            ReadCalls++;
            return base.Read(buffer);
        }
    }
}
